#!/usr/bin/env bash
# Prepares a separate, one-shot systemd-boot entry for exercising mlx-init.
# The normal entry and its initramfs are read-only inputs. The test image uses
# mkinitcpio's classic udev init, because that init carries `init=` across the
# switch to the real root; the systemd initramfs does not.
#
# Nothing is armed until every build and verification has succeeded. Existing
# boot assets which were not generated by this script are never replaced.
#
# Usage:
#   tools/prepare_mlx_init_boot.sh [options]
#
# Options:
#   --source-entry FILE       normal systemd-boot entry (default: current)
#   --entry FILE              generated entry (default: mlx-init-test.conf)
#   --image FILE              generated image (derived from source image)
#   --config FILE             retained mkinitcpio config
#                             (default: /etc/mkinitcpio-mlx-init.conf)
#   --mkinitcpio-config FILE  source config (default: /etc/mkinitcpio.conf)
#   --kernel RELEASE          kernel release (default: uname -r)
#   --compiler FILE           Mlx compiler (default: checkout compiler)
#
# Run as root. To cancel after preparation and before reboot:
#   bootctl set-oneshot ''
set -euo pipefail

prepare_repo_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
prepare_marker='# Generated by tools/prepare_mlx_init_boot.sh.'
prepare_expected_systemd_hooks='base systemd autodetect microcode kms modconf block keyboard sd-vconsole plymouth filesystems'
prepare_classic_hooks='base udev autodetect microcode kms mlx-splash modconf block keyboard keymap consolefont filesystems fsck'
prepare_oneshot_variable_glob='/sys/firmware/efi/efivars/LoaderEntryOneShot-*'
prepare_lsinitcpio_command=lsinitcpio
prepare_readelf_command=readelf
prepare_splash_binary=/usr/bin/mlx/mlx-splash

prepare_die() {
    echo "prepare_mlx_init_boot.sh: $*" >&2
    exit 2
}

prepare_usage() {
    sed -n '2,/^set -euo pipefail$/p' "${BASH_SOURCE[0]}" | sed '$d; s/^# \{0,1\}//'
}

prepare_require_absolute() {
    [[ $2 == /* ]] || prepare_die "$1 must be an absolute path"
}

prepare_realpath() {
    realpath -m -- "$1"
}

# Prints the words in one single-line shell array assignment. The boot helper
# deliberately accepts only this simple form: interpreting arbitrary config
# as shell would widen a root-owned boot operation needlessly.
prepare_array_words() {
    local file=$1 name=$2 values count
    count=$(grep -Ec "^[[:space:]]*${name}[[:space:]]*=[[:space:]]*\\([^)]*\\)[[:space:]]*(#.*)?$" "$file" || true)
    [[ $count -eq 1 ]] || prepare_die "$file must contain exactly one single-line $name=(...) assignment"
    values=$(sed -n -E "s|^[[:space:]]*${name}[[:space:]]*=[[:space:]]*\\(([^)]*)\\)[[:space:]]*(#.*)?$|\\1|p" "$file")
    # Collapse whitespace so comparisons below are exact but formatting is not.
    read -r -a prepare_array_values <<< "$values"
    printf '%s\n' "${prepare_array_values[*]}"
}

prepare_has_word() {
    local words=$1 wanted=$2 word
    for word in $words; do
        [[ $word == "$wanted" ]] && return 0
    done
    return 1
}

# This is intentionally not a general systemd-to-busybox converter. Storage
# hooks are boot-critical, so only the audited, unencrypted host layout is
# accepted; encrypted, LVM, RAID or otherwise different layouts stop here.
prepare_make_classic_config() {
    local source=$1 output=$2 hooks modules
    hooks=$(prepare_array_words "$source" HOOKS)
    modules=$(prepare_array_words "$source" MODULES)
    [[ $hooks == "$prepare_expected_systemd_hooks" ]] || prepare_die \
        "unsupported mkinitcpio HOOKS: $hooks (refusing to guess storage-hook conversions)"
    prepare_has_word "$modules" amdgpu || prepare_die \
        "$source must put amdgpu in MODULES so KMS is available before mlx-splash"

    awk -v marker="$prepare_marker" -v hooks="$prepare_classic_hooks" '
        BEGIN { print marker; replaced = 0 }
        /^[[:space:]]*HOOKS[[:space:]]*=/ {
            print "HOOKS=(" hooks ")"
            replaced += 1
            next
        }
        { print }
        END { if (replaced != 1) exit 1 }
    ' "$source" > "$output" || prepare_die "could not create the classic mkinitcpio config"

    [[ $(prepare_array_words "$output" HOOKS) == "$prepare_classic_hooks" ]] ||
        prepare_die "the generated mkinitcpio config has unexpected hooks"
}

prepare_main_initrd() {
    local entry=$1 line count
    count=$(grep -Ec '^initrd[[:space:]]+/initramfs-[^[:space:]]+\.img[[:space:]]*$' "$entry" || true)
    [[ $count -eq 1 ]] || prepare_die "$entry must contain exactly one main /initramfs-*.img line"
    line=$(sed -n -E 's|^initrd[[:space:]]+(/initramfs-[^[:space:]]+\.img)[[:space:]]*$|\1|p' "$entry")
    printf '%s\n' "$line"
}

prepare_validate_source_entry() {
    local entry=$1
    [[ -f $entry ]] || prepare_die "boot entry is missing: $entry"
    [[ $(grep -Ec '^title[[:space:]]+' "$entry" || true) -eq 1 ]] || prepare_die "$entry must contain exactly one title"
    [[ $(grep -Ec '^options[[:space:]]+' "$entry" || true) -eq 1 ]] || prepare_die "$entry must contain exactly one options line"
    if grep -Eq '(^|[[:space:]])init=[^[:space:]]+' "$entry"; then
        prepare_die "$entry already selects an init program"
    fi
    prepare_main_initrd "$entry" >/dev/null
}

prepare_build_entry() {
    local source=$1 output=$2 image_path=$3 main_initrd
    main_initrd=$(prepare_main_initrd "$source")
    awk -v marker="$prepare_marker" -v image="$image_path" -v main="$main_initrd" '
        BEGIN { print marker; title = 0; initrd = 0; options = 0 }
        /^title[[:space:]]+/ {
            print "title MLX init one-shot test"
            title += 1
            next
        }
        $1 == "initrd" && $2 == main {
            print "initrd " image
            initrd += 1
            next
        }
        /^options[[:space:]]+/ {
            print $0 " init=/usr/bin/mlx/mlx-init"
            options += 1
            next
        }
        { print }
        END { if (title != 1 || initrd != 1 || options != 1) exit 1 }
    ' "$source" > "$output" || prepare_die "could not create the test boot entry"
}

prepare_verify_entry() {
    local entry=$1 image_path=$2 options token init_count=0
    grep -Fxq "$prepare_marker" "$entry" || prepare_die "$entry has no generator marker"
    [[ $(grep -Fxc 'title MLX init one-shot test' "$entry" || true) -eq 1 ]] || prepare_die "$entry has an unexpected title"
    [[ $(grep -Fxc "initrd $image_path" "$entry" || true) -eq 1 ]] || prepare_die "$entry does not select $image_path exactly once"
    [[ $(grep -Ec '^options[[:space:]]+' "$entry" || true) -eq 1 ]] || prepare_die "$entry must contain exactly one options line"
    options=$(sed -n -E 's/^options[[:space:]]+//p' "$entry")
    for token in $options; do
        [[ $token == init=* ]] && init_count=$((init_count + 1))
    done
    [[ $init_count -eq 1 ]] || prepare_die "$entry must contain exactly one init= option"
    prepare_has_word "$options" 'init=/usr/bin/mlx/mlx-init' || prepare_die "$entry selects the wrong init program"
}

prepare_archive_has() {
    local manifest=$1 path=$2
    grep -Fxq "$path" "$manifest" || grep -Fxq "/$path" "$manifest"
}

prepare_verify_image() (
    local image=$1 kernel=$2 config_dump manifest extract interpreter interpreter_path
    config_dump=$(mktemp)
    manifest=$(mktemp)
    extract=$(mktemp -d)
    trap 'rm -f -- "$config_dump" "$manifest"; rm -rf -- "$extract"' EXIT

    "$prepare_lsinitcpio_command" -c "$image" > "$config_dump"
    [[ $(prepare_array_words "$config_dump" HOOKS) == "$prepare_classic_hooks" ]] ||
        prepare_die "$image was not built with the audited classic hooks"
    "$prepare_lsinitcpio_command" -l "$image" > "$manifest"

    prepare_archive_has "$manifest" 'hooks/mlx-splash' || prepare_die "$image lacks the mlx-splash runtime hook"
    prepare_archive_has "$manifest" 'usr/bin/mlx/mlx-splash' || prepare_die "$image lacks mlx-splash"
    prepare_archive_has "$manifest" 'usr/bin/mlx/mlx-splashctl' || prepare_die "$image lacks mlx-splashctl"
    grep -Eq '^/?usr/share/fonts/.*(Sans|LiberationSans|NotoSans).*\.ttf$' "$manifest" || prepare_die "$image lacks the proportional splash font"
    grep -Eq '^/?usr/share/fonts/.*(Mono|monospace).*\.ttf$' "$manifest" || prepare_die "$image lacks the monospaced splash font"
    grep -Fq "usr/lib/modules/$kernel/kernel/drivers/gpu/drm/amd/amdgpu/amdgpu.ko" "$manifest" ||
        prepare_die "$image lacks the amdgpu kernel module for $kernel"
    if grep -Eq '(^|/)(hooks/plymouth|usr/bin/plymouth|usr/bin/plymouthd)$' "$manifest"; then
        prepare_die "$image still contains Plymouth"
    fi

    interpreter=$(LC_ALL=C "$prepare_readelf_command" -lW "$prepare_splash_binary" 2>/dev/null |
        sed -n -E 's/.*Requesting program interpreter:[[:space:]]*([^]]+)\].*/\1/p')
    if [[ -n $interpreter ]]; then
        interpreter_path=${interpreter#/}
        prepare_archive_has "$manifest" "$interpreter_path" || prepare_die "$image lacks the splash interpreter $interpreter"
    fi

    (cd "$extract" && "$prepare_lsinitcpio_command" -x "$image" >/dev/null)
    [[ -f $extract/init ]] || prepare_die "$image lacks classic /init"
    [[ $(head -n 1 "$extract/init") == '#!/usr/bin/ash' ]] || prepare_die "$image does not use mkinitcpio's classic ash init"
    [[ -f $extract/hooks/mlx-splash ]] || prepare_die "$image lacks the extracted mlx-splash hook"
    grep -Eq '^[[:space:]]*run_hook\(\)' "$extract/hooks/mlx-splash" || prepare_die "mlx-splash hook has no run_hook"
    grep -Eq '^[[:space:]]*run_latehook\(\)' "$extract/hooks/mlx-splash" || prepare_die "mlx-splash hook has no root handoff"
    if grep -Fq 'plymouth.enable' "$extract/hooks/mlx-splash"; then
        prepare_die "mlx-splash must not inherit Plymouth's disable switch"
    fi

)

prepare_require_root() {
    [[ $(id -u) -eq 0 ]] || prepare_die "run this boot preparation as root"
}

prepare_check_commands() {
    local command
    for command in awk bootctl grep head install jq lsinitcpio mkinitcpio mktemp mv readelf realpath sed sha256sum uname; do
        command -v "$command" >/dev/null 2>&1 || prepare_die "required program is missing: $command"
    done
}

prepare_check_existing_oneshot() {
    local matches=()
    shopt -s nullglob
    matches=($prepare_oneshot_variable_glob)
    shopt -u nullglob
    if [[ ${#matches[@]} -ne 0 ]]; then
        prepare_die "a boot-loader one-shot entry is already armed; preserve it or clear it explicitly with: bootctl set-oneshot ''"
    fi
}

prepare_boot_entries_json() {
    LC_ALL=C bootctl list --json=short
}

prepare_check_source_default() {
    local source_id=$1 listing
    listing=$(prepare_boot_entries_json) || prepare_die "bootctl could not list the boot entries"
    jq -e --arg id "$source_id" 'type == "array" and any(.[]; .id == $id and .isDefault == true)' \
        >/dev/null <<< "$listing" || prepare_die "$source_id is not the persistent fallback boot entry"
}

prepare_boot_entry_known() {
    local entry_id=$1 listing
    listing=$(prepare_boot_entries_json) || return 1
    jq -e --arg id "$entry_id" 'type == "array" and any(.[]; .id == $id)' >/dev/null <<< "$listing"
}

prepare_check_owned_target() {
    local kind=$1 path=$2
    [[ ! -e $path ]] && return 0
    [[ -f $path ]] || prepare_die "refusing to replace non-file $path"
    grep -Fxq "$prepare_marker" "$path" || prepare_die "refusing to replace unrelated $kind: $path"
}

prepare_atomic_install() {
    local source=$1 target=$2 mode=$3 directory temporary
    directory=$(dirname "$target")
    temporary=$(mktemp "$directory/.${target##*/}.new.XXXXXX")
    install -m "$mode" "$source" "$temporary"
    mv -f -- "$temporary" "$target"
}

prepare_hash() {
    sha256sum -- "$1" | awk '{print $1}'
}

prepare_assert_fallback_unchanged() {
    local source_entry=$1 entry_hash=$2 source_image=$3 image_hash=$4
    [[ $(prepare_hash "$source_entry") == "$entry_hash" ]] || prepare_die "the fallback boot entry changed during preparation"
    [[ $(prepare_hash "$source_image") == "$image_hash" ]] || prepare_die "the fallback initramfs changed during preparation"
}

prepare_check_programs_for_greeter() {
    local program path missing=0
    for program in mlx-ipcd mlx-netd mlx-compositor; do
        path=/usr/bin/mlx/$program
        if [[ ! -x $path ]]; then
            echo "prepare_mlx_init_boot.sh: required installed program is missing: $path" >&2
            missing=1
        fi
    done
    [[ $missing -eq 0 ]] || prepare_die "install the MLXIPC, network and compositor programs before preparing the boot"
}

prepare_install_components() {
    local compiler=$1 build=$2
    prepare_check_programs_for_greeter

    "$compiler" --quiet "$prepare_repo_root/projects/init/main.mlx" -o "$build/mlx-init"
    "$compiler" --quiet "$prepare_repo_root/projects/init/tool.mlx" -o "$build/mlx-initctl"
    install -d -m 755 /usr/bin/mlx
    install -m 755 "$build/mlx-init" "$build/mlx-initctl" /usr/bin/mlx/

    # The test entry alone selects mlx-init. Do not alter the display-manager
    # alias, mask the normal systemd services, or otherwise weaken fallback.
    "$prepare_repo_root/tools/install_login.sh" --prefix /usr --compiler "$compiler"
    "$prepare_repo_root/tools/install_splash.sh" --prefix /usr "$compiler"

    local path
    for path in \
        /usr/bin/mlx/mlx-init /usr/bin/mlx/mlx-initctl \
        /usr/bin/mlx/mlx-login /usr/bin/mlx/mlx-greeter \
        /usr/bin/mlx/mlx-splash /usr/bin/mlx/mlx-splashctl \
        /usr/lib/initcpio/install/mlx-splash /usr/lib/initcpio/hooks/mlx-splash; do
        [[ -x $path ]] || prepare_die "component installation left out $path"
    done
    grep -Fxq 'ready = socket:/run/mlx/bus' /etc/mlx/init/services/mlx-ipcd.service ||
        prepare_die "mlx-ipcd's mlx-init service does not use socket readiness"
    grep -Fxq 'disabled = yes' /etc/mlx/init/services/mlx-splash.service ||
        prepare_die "the real-root mlx-init splash fallback is not disabled"
    prepare_splash_binary=/usr/bin/mlx/mlx-splash
}

prepare_build_image() {
    local config=$1 kernel=$2 output=$3
    mkinitcpio -c "$config" -k "$kernel" -g "$output"
}

prepare_arm_oneshot() {
    bootctl set-oneshot "$1"
}

prepare_current_source_entry() {
    local boot_root current
    boot_root=$(bootctl -x) || prepare_die "bootctl could not locate the boot partition"
    current=$(LC_ALL=C bootctl status --no-pager |
        sed -n -E 's/^[[:space:]]*Current Entry:[[:space:]]*([^[:space:]]+)[[:space:]]*$/\1/p')
    [[ -n $current && $current != */* && $current == *.conf ]] || prepare_die "could not derive the current boot entry"
    printf '%s/loader/entries/%s\n' "${boot_root%/}" "$current"
}

prepare_main() {
    local source_entry='' test_entry='' image='' retained_config=/etc/mkinitcpio-mlx-init.conf
    local mkinitcpio_source=/etc/mkinitcpio.conf kernel compiler
    kernel=$(uname -r)
    compiler=$prepare_repo_root/mlx-out/bin/compiler/mlx4

    while [[ $# -gt 0 ]]; do
        case $1 in
            --source-entry) [[ $# -ge 2 ]] || prepare_die "$1 needs a path"; source_entry=$2; shift 2 ;;
            --entry) [[ $# -ge 2 ]] || prepare_die "$1 needs a path"; test_entry=$2; shift 2 ;;
            --image) [[ $# -ge 2 ]] || prepare_die "$1 needs a path"; image=$2; shift 2 ;;
            --config) [[ $# -ge 2 ]] || prepare_die "$1 needs a path"; retained_config=$2; shift 2 ;;
            --mkinitcpio-config) [[ $# -ge 2 ]] || prepare_die "$1 needs a path"; mkinitcpio_source=$2; shift 2 ;;
            --kernel) [[ $# -ge 2 ]] || prepare_die "$1 needs a release"; kernel=$2; shift 2 ;;
            --compiler) [[ $# -ge 2 ]] || prepare_die "$1 needs a path"; compiler=$2; shift 2 ;;
            -h|--help) prepare_usage; return 0 ;;
            *) prepare_die "unknown option: $1" ;;
        esac
    done

    prepare_require_root
    prepare_check_commands
    [[ -n $source_entry ]] || source_entry=$(prepare_current_source_entry)
    prepare_require_absolute --source-entry "$source_entry"
    prepare_require_absolute --config "$retained_config"
    prepare_require_absolute --mkinitcpio-config "$mkinitcpio_source"
    prepare_require_absolute --compiler "$compiler"
    source_entry=$(prepare_realpath "$source_entry")
    retained_config=$(prepare_realpath "$retained_config")
    mkinitcpio_source=$(prepare_realpath "$mkinitcpio_source")
    compiler=$(prepare_realpath "$compiler")
    [[ -x $compiler ]] || prepare_die "Mlx compiler is missing: $compiler"
    [[ -d /usr/lib/modules/$kernel ]] || prepare_die "kernel modules are missing for $kernel"
    [[ -f $mkinitcpio_source ]] || prepare_die "mkinitcpio config is missing: $mkinitcpio_source"
    prepare_validate_source_entry "$source_entry"

    local entry_directory boot_root source_id source_initrd source_image image_entry_path test_id
    entry_directory=$(dirname "$source_entry")
    [[ ${entry_directory##*/} == entries && $(basename "$(dirname "$entry_directory")") == loader ]] ||
        prepare_die "$source_entry is not below a loader/entries directory"
    boot_root=$(prepare_realpath "$entry_directory/../..")
    source_id=${source_entry##*/}
    source_initrd=$(prepare_main_initrd "$source_entry")
    [[ $source_initrd == /* && $source_initrd != *'/../'* && $source_initrd != */.. ]] ||
        prepare_die "unsafe initrd path in $source_entry"
    source_image=$(prepare_realpath "$boot_root$source_initrd")
    [[ -f $source_image ]] || prepare_die "fallback initramfs is missing: $source_image"

    [[ -n $test_entry ]] || test_entry=$entry_directory/mlx-init-test.conf
    test_entry=$(prepare_realpath "$test_entry")
    prepare_require_absolute --entry "$test_entry"
    [[ $(dirname "$test_entry") == "$entry_directory" ]] || prepare_die "the test entry must stay in $entry_directory"
    test_id=${test_entry##*/}
    [[ $test_id == *.conf && $test_id != */* ]] || prepare_die "invalid test entry name: $test_id"
    [[ $test_id != "$source_id" ]] || prepare_die "the test entry must differ from the fallback entry"

    if [[ -z $image ]]; then
        image=$boot_root/${source_initrd#/}
        image=${image%.img}-mlx-init.img
    fi
    image=$(prepare_realpath "$image")
    prepare_require_absolute --image "$image"
    [[ $image == "$boot_root/"* ]] || prepare_die "the test image must stay below $boot_root"
    [[ $image != "$source_image" ]] || prepare_die "the test image must differ from the fallback initramfs"
    image_entry_path=/${image#"$boot_root/"}

    prepare_check_owned_target config "$retained_config"
    prepare_check_owned_target entry "$test_entry"
    if [[ -e $image && ! -e $test_entry ]]; then
        prepare_die "refusing to replace an image without its generated entry: $image"
    fi
    [[ ! -e $image || -f $image ]] || prepare_die "refusing to replace non-file $image"
    prepare_check_existing_oneshot
    prepare_check_source_default "$source_id"

    local source_entry_hash source_image_hash
    source_entry_hash=$(prepare_hash "$source_entry")
    source_image_hash=$(prepare_hash "$source_image")

    local image_directory image_build entry_build scratch config_candidate image_candidate entry_candidate
    image_directory=$(dirname "$image")
    [[ -d $image_directory && -d $entry_directory ]] || prepare_die "boot output directories are missing"
    image_build=$(mktemp -d "$image_directory/.mlx-init-image.XXXXXX")
    entry_build=$(mktemp -d "$entry_directory/.mlx-init-entry.XXXXXX")
    scratch=$(mktemp -d)
    config_candidate=$scratch/mkinitcpio.conf
    image_candidate=$image_build/initramfs.img
    entry_candidate=$entry_build/$test_id
    prepare_cleanup() {
        rm -rf -- "$image_build" "$entry_build" "$scratch"
    }
    trap prepare_cleanup EXIT

    mkdir -p "$scratch/components"
    prepare_make_classic_config "$mkinitcpio_source" "$config_candidate"
    prepare_install_components "$compiler" "$scratch/components"
    prepare_build_image "$config_candidate" "$kernel" "$image_candidate"
    [[ -s $image_candidate ]] || prepare_die "mkinitcpio produced no image"
    prepare_verify_image "$image_candidate" "$kernel"

    prepare_build_entry "$source_entry" "$entry_candidate" "$image_entry_path"
    prepare_verify_entry "$entry_candidate" "$image_entry_path"
    prepare_assert_fallback_unchanged "$source_entry" "$source_entry_hash" "$source_image" "$source_image_hash"

    prepare_atomic_install "$config_candidate" "$retained_config" 644
    chmod 600 "$image_candidate"
    mv -f -- "$image_candidate" "$image"
    chmod 600 "$entry_candidate"
    mv -f -- "$entry_candidate" "$test_entry"

    prepare_verify_image "$image" "$kernel"
    prepare_verify_entry "$test_entry" "$image_entry_path"
    prepare_assert_fallback_unchanged "$source_entry" "$source_entry_hash" "$source_image" "$source_image_hash"
    prepare_boot_entry_known "$test_id" || prepare_die "bootctl does not recognize $test_id"

    echo
    echo "Prepared $test_id with mlx-init and the initramfs mlx-splash."
    echo "Fallback entry and image are unchanged: $source_id"
    echo "The following command is the final mutation; cancel before reboot with: bootctl set-oneshot ''"

    # Removing scratch state before arming makes the EFI one-shot selection
    # the final mutation. No fallible verification follows it.
    prepare_cleanup
    trap - EXIT
    prepare_arm_oneshot "$test_id"
}

if [[ ${BASH_SOURCE[0]} == "$0" ]]; then
    prepare_main "$@"
fi
